            + (texture_value & 0xfffu)) * 0x100u;
        const auto prefix = prefix_before_byte + read_field<std::uint8_t>(effect, 0xc0);
        // Original second __allmul operand is high20h/low0 = 2^37.
        const std::uint32_t high = prefix << 5;
