    Vec2 = 6,         // 00BD65C7: t[1], t[2] as floats
    Matrix4 = 7,      // 00BD664A: t[i][j], i and j in 1..4, row major
    Vec4 = 8,         // 00BD66D8: t[1]..t[4] as floats
