bool equal_insensitive(const std::string& a, const std::string& b) noexcept {
    if (a.size() != b.size()) return false;
    for (std::size_t i = 0; i < a.size(); ++i) {
        const unsigned char lhs = static_cast<unsigned char>(a[i]);
        const unsigned char rhs = static_cast<unsigned char>(b[i]);
        if (std::tolower(lhs) != std::tolower(rhs)) return false;
    }
    return true;
}

bool hidden_property_bool(const SceneProperty* prop) noexcept {
    // 0046D3BC..0046D3CA reads Hidden's retained byte. Keep this host's
    // existing after-gate ordering and raw fallback outside owning B data.
    if (prop != nullptr && equal_insensitive(prop->type_letter, "B")
        && prop->has_boolean) {
        return prop->boolean_value != 0;
    }
    return scene_property_bool(prop);
}

bool director_property_bool(const SceneProperty* prop) noexcept {
    // 008238FD..008239A7 uses stored director bytes. Keep the existing
