    // This owning-tree projection validates its supported domain on a copy;
    // native malformed-input failure, aliases and rollback are not modeled.
    ScenePropertyBlock captured = existing != nullptr ? existing->block : ScenePropertyBlock{};
    for (const std::string& base : group.bases) {
        merge_property_block(captured, this->group(base)->block, true, true);
    }
    merge_property_block(captured, group.block, true, true);
    if (existing != nullptr) {
        existing->block = std::move(captured);
        existing->bases = std::move(group.bases);
    } else {
        group.block = std::move(captured);
        groups_.push_back(std::move(group));
    }
}

void merge_group_into(const PropertyLibrary& library, const std::string& name,
    ScenePropertyBlock& bag) {
    const PropertyGroupDefinition* group = library.group(name);
    if (group == nullptr) return;
    merge_property_block(bag, group->block, false);
}

bool retain_start_speed(const ScenePropertyBlock& bag, GameSceneEntityRecord& record) {
    const SceneProperty* prop = bag.find(kSceneUnitStartSpeedKey);
    const bool retained_float = prop != nullptr
        && equal_insensitive(prop->type_letter, "F") && prop->has_float;
    if (prop == nullptr || (!retained_float && prop->values.empty())) return false;
    record.start_speed_present = true;
    // 00823599 compares the record type with zero. Type 0 (`I`) takes
    // CVTSI2SS at 0082359E; every other type takes MOVSS at 008235A5.
    record.start_speed_type = prop->type_letter == "I"
        ? static_cast<int>(ScenePropertyType::Int)
        : static_cast<int>(ScenePropertyType::Float);
    if (!prop->values.empty()) {
        // Preserve the existing incidental integer reading when available.
        std::int32_t as_int = 0;
        if (scene_scan_int(prop->values.back(), as_int)) record.start_speed_int = as_int;
        if (!retained_float) {
            float as_float = 0.0f;
            if (scene_scan_float(prop->values.back(), as_float)) record.start_speed_float = as_float;
        }
    }
    // Successful nonempty explicit F owns +0Ch's float32 independently of
    // diagnostics. This availability is not an empty-F parse action.
    if (retained_float) record.start_speed_float = prop->float_value;
    return true;
}

bool retain_airfield_runway(const ScenePropertyBlock& bag, bsp::AirOpsDeck& deck) {
    const SceneProperty* width = bag.find("RunwayWidth");
    const SceneProperty* length = bag.find("RunwayLength");
    const auto retained = [](const SceneProperty* prop) {
        return prop != nullptr && equal_insensitive(prop->type_letter, "F") && prop->has_float;
    };
    // 006D3D20/006D3D4B read the stored +0Ch float. Keep the existing raw
    // availability checks and scans for properties without a retained F value.
    if (width == nullptr || (!retained(width) && width->values.empty())
        || length == nullptr || (!retained(length) && length->values.empty())) return false;
    const auto read = [&retained](const SceneProperty* prop, float& value) {
        if (retained(prop)) {
            value = prop->float_value;
            return true;
        }
        return scene_scan_float(prop->values.back(), value);
    };
    float width_value = 0.0f, length_value = 0.0f;
    if (!read(width, width_value) || !read(length, length_value)) return false;
    deck.runway_width = width_value;
    deck.runway_length = length_value;
    deck.runway_from_scene = true;
    return true;
}

void retain_scene_raw_word(const SceneProperty* prop, bool& present, std::int32_t& raw) {
    if (prop == nullptr) return;
    std::int32_t value = 0;
    // 006F27FC/006F2823 copy the stored +0Ch DWORD without type conversion.
    if (equal_insensitive(prop->type_letter, "F") && prop->has_float) {
        std::memcpy(&value, &prop->float_value, sizeof value);
    } else if (equal_insensitive(prop->type_letter, "I") && prop->has_integer) {
        value = prop->integer_value;
    } else {
        if (prop->values.empty()) return;
        float as_float = 0.0f;
        if (prop->type_letter == "I" && scene_scan_int(prop->values.back(), value)) {
            // Preserve the existing I-first scan and its integer word.
        } else if (scene_scan_float(prop->values.back(), as_float)) {
            std::memcpy(&value, &as_float, sizeof value);
        } else {
            return;
        }
    }
    present = true;
    raw = value;
}

// Packet cc9_land_convoy_members. 00743450's scene reads (007434A4..007437B0):
// five float fields read type 1's retained float32 or convert an integer;
// Rows/Columns read integers and Reverse a byte. Then the slot map: every
// slot -1, and for n = 1..4
// the block "Type<n>" (type tag 6; absent gives a null bag) and its enum `Type`,
// for m = 1..4 its integer "Position<m>": 0 fills every slot with the type, a
// positive value fills slot value-1 (the later write wins), a negative one nothing.
// The bag here is already merged with the library group, which is what makes
// the unauthored `Type1.Position1 = 0` of landconvoy.props apply.
void retain_land_convoy_roster(const ScenePropertyBlock& bag, GameSceneEntityRecord& record,
    const PropertyLibrary& library) {
    const auto scalar = [&](const char* key, float fallback) {
        const SceneProperty* prop = bag.find(key);
        if (prop == nullptr || prop->values.empty()) return fallback;
        float f = fallback;
        std::int32_t i = 0;
        if (prop->type_letter == "I" && scene_scan_int(prop->values.back(), i))
            return static_cast<float>(i);
        if (scene_scan_float(prop->values.back(), f)) return f;
        if (prop->type_letter == "B") return prop->values.back() == "true" ? 1.0f : 0.0f;
        return fallback;
    };
    const auto integer = [&](const ScenePropertyBlock& block, const char* key, std::int32_t fallback) {
        const SceneProperty* prop = block.find(key);
        std::int32_t i = fallback;
        if (prop != nullptr && !prop->values.empty()) scene_scan_int(prop->values.back(), i);
        return i;
    };
    const auto retained_integer = [&](const char* key, std::int32_t fallback) {
        const SceneProperty* prop = bag.find(key);
        // 007434F8/00743514 copy the stored dimension words at +0Ch.
        if (prop != nullptr && equal_insensitive(prop->type_letter, "I") && prop->has_integer)
            return prop->integer_value;
        return integer(bag, key, fallback);
    };
    const auto retained_position_integer = [&](const ScenePropertyBlock& block, const char* key) {
        const SceneProperty* prop = block.find(key);
        // 00743791 consumes the stored Position word before the slot branches.
        if (prop != nullptr && equal_insensitive(prop->type_letter, "I") && prop->has_integer)
            return prop->integer_value;
        return integer(block, key, -1);
    };
    const auto retained_scalar = [&](const char* key, float fallback) {
        const SceneProperty* prop = bag.find(key);
        // 007434CC..007435DE consume +0Ch, not parser diagnostics. This
        // availability flag binds successful nonempty explicit F only.
        if (prop != nullptr && equal_insensitive(prop->type_letter, "F") && prop->has_float)
            return prop->float_value;
        return scalar(key, fallback);
    };
    const auto retained_reverse = [&] {
        const SceneProperty* prop = bag.find("Reverse");
        // 007434B0 copies the stored Reverse byte; retain the old scalar fallback.
        if (prop != nullptr && equal_insensitive(prop->type_letter, "B") && prop->has_boolean)
            return prop->boolean_value != 0;
        return scalar("Reverse", 0.0f) != 0.0f;
    };
    record.land_convoy_keys = true;
    record.convoy_rows = retained_integer("Rows", 0);
    record.convoy_columns = retained_integer("Columns", 0);
    record.convoy_row_gap = retained_scalar("RowGap", 0.0f);
    record.convoy_column_gap = retained_scalar("ColumnGap", 0.0f);
    record.convoy_hp = retained_scalar("HP", 0.0f);
    record.convoy_speed = retained_scalar("Speed", 0.0f);
    record.convoy_offset = retained_scalar("Offset", 0.0f);
    record.convoy_reverse = retained_reverse();
    if (const SceneProperty* path = bag.find("Path"); path != nullptr && !path->values.empty()) {
        std::string value = path->values.back();
        if (value.size() >= 2 && value.front() == '"' && value.back() == '"')
            value = value.substr(1, value.size() - 2);
        record.convoy_path = value;
    }
    const int slots = record.convoy_rows * record.convoy_columns;
    record.convoy_slots.assign(slots > 0 ? static_cast<std::size_t>(slots) : 0u, -1);
    record.convoy_slot_symbols.assign(record.convoy_slots.size(), std::string());
    for (int n = 1; n <= 4; ++n) {
        char key[16];
        std::snprintf(key, sizeof(key), "Type%d", n);
        const ScenePropertyBlock* sub = nullptr;
        for (const auto& block : bag.blocks) {
            if (equal_insensitive(block.first, key)) { sub = &block.second; break; }
        }
        if (sub == nullptr) continue;
        int type = 0;
        std::string symbol;
        const SceneEnumProperty e = scene_enum_property(*sub, "Type");
        if (e.present) {
            symbol = e.symbol;
            if (!library.resolve_symbol(e.table, e.symbol, type)) type = 0;
        }
        for (int m = 1; m <= 4; ++m) {
            char position_key[16];
            std::snprintf(position_key, sizeof(position_key), "Position%d", m);
            const std::int32_t position = retained_position_integer(*sub, position_key);
            if (position == 0) {
                for (std::size_t s = 0; s < record.convoy_slots.size(); ++s) {
                    record.convoy_slots[s] = type;
                    record.convoy_slot_symbols[s] = symbol;
                }
            } else if (position > 0
                       && static_cast<std::size_t>(position) <= record.convoy_slots.size()) {
                record.convoy_slots[static_cast<std::size_t>(position - 1)] = type;
                record.convoy_slot_symbols[static_cast<std::size_t>(position - 1)] = symbol;
            }
        }
    }
}

// 007B352E..007B3604, only the fresh kind-1 PathPoints/Pos data projection.
// The native asks for Point%002i using its current point count (00415870),
// copies the three Pos lanes unchanged and appends once before the next lookup.
// Other source-holder kinds, Group, allocation, derived lengths and native
// entity construction are not implemented by this retention binding.
void retain_path_points(const ScenePropertyBlock& bag, GameSceneEntityRecord& record) {
    const ScenePropertyBlock* points = nullptr;
    for (const auto& block : bag.blocks) {
        if (equal_insensitive(block.first, "PathPoints")) { points = &block.second; break; }
    }
    if (points == nullptr) {
        record.path_points_error = "PathPoints block absent";
        return;
    }
    for (std::size_t index = 0;; ++index) {
        char key[40];
        std::snprintf(key, sizeof(key), "Point%02zu", index);
        // A scalar at this key has native type != 6 and terminates the loop.
        if (points->find(key) != nullptr) break;
        const ScenePropertyBlock* point = nullptr;
        for (const auto& block : points->blocks) {
            if (equal_insensitive(block.first, key)) { point = &block.second; break; }
        }
        if (point == nullptr) break;
        const SceneProperty* position = point->find("Pos");
        std::array<float, 3> value{};
        bool valid = position != nullptr && position->has_vector3;
        if (valid) {
            // 007B35A8..007B35D2 copies the three stored Pos lanes directly.
            // A parsed present-empty V3 is a zero vector, not missing data.
            value = position->vector3;
        } else if (position != nullptr && position->type_letter == "V3"
            && position->values.size() == value.size()) {
            // Explicit legacy fallback for source-authored raw bags that did
            // not pass through the typed parser. Native-derived payloads above
            // never reparse their diagnostic tokens through strtod.
            valid = true;
            for (std::size_t lane = 0; valid && lane < value.size(); ++lane) {
                valid = scene_scan_float(position->values[lane], value[lane]);
            }
        }
        if (!valid) {
            // The native dereferences the schema-backed V3 value directly.
            // An unsupported/malformed bag cannot become invented geometry.
            record.path_points_error = std::string(key) + ".Pos is not a readable V3";
            record.path_points_local.clear();
            return;
        }
        record.path_points_local.push_back(value);
    }
    record.path_points_retained = true;
}

