        {SingletonAllocationKind::object, native_bytes, sizeof(T)});
    if (!storage) return nullptr;
    T* owner = nullptr;
    try {
        owner = ::new (storage) T(allocation);
        return &constructor(*owner);
    } catch (...) {
        if (owner) owner->~T();
        singleton_lifetime_free(storage);
        throw;
